import{_ as o,o as r,c as l,ag as i}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-架构设计-质量属性与评估","description":"","frontmatter":{"title":"架构师-备考 综合知识-架构设计-质量属性与评估"},"headers":[],"relativePath":"综合知识/架构设计/质量属性与评估.md","filePath":"综合知识/架构设计/质量属性与评估.md","lastUpdated":null}'),s={name:"综合知识/架构设计/质量属性与评估.md"};function a(n,t,d,e,g,h){return r(),l("div",null,[...t[0]||(t[0]=[i('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 六大质量属性：性能/可用性/安全性/可修改性/可测试性/易用性</li><li>[x] 可靠性（MTTF/MTBF）与鲁棒性（Robustness）</li><li>[x] 可变性（Variability）概念</li><li>[x] 运行期 vs 开发期质量属性分类</li><li>[x] 质量属性场景六要素</li><li>[x] ATAM 架构权衡分析法</li><li>[x] SAAM 软件架构分析方法</li><li>[x] CBAM 成本效益分析法</li><li>[x] 非功能性需求四分类（操作性/性能/安全性/文化）</li><li>[x] 敏感点、权衡点与风险决策</li><li>[x] 效用树（Utility Tree）</li><li>[x] 质量属性与架构策略对应关系</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、质量属性概述" tabindex="-1">一、质量属性概述 <a class="header-anchor" href="#一、质量属性概述" aria-label="Permalink to &quot;一、质量属性概述&quot;">​</a></h3><blockquote><p>软件系统质量属性（Quality Attribute）是一个系统的可测量或可测试的属性，用来描述系统满足利益相关者需求的程度。</p></blockquote><p><strong>质量属性场景六要素：</strong></p><ol><li><strong>刺激源</strong>（Source）— 谁发出的刺激</li><li><strong>刺激</strong>（Stimulus）— 触发系统的事件</li><li><strong>环境</strong>（Environment）— 事件发生时的条件</li><li><strong>制品</strong>（Artifact）— 被影响的系统组成部分</li><li><strong>响应</strong>（Response）— 系统对刺激的反应行为</li><li><strong>响应度量</strong>（Response Measure）— 可量化的评估指标</li></ol><blockquote><p>简化三要素（场景最小描述）：<strong>刺激、环境、响应</strong></p></blockquote><hr><h3 id="二、六大核心质量属性-★" tabindex="-1">二、六大核心质量属性 ★ <a class="header-anchor" href="#二、六大核心质量属性-★" aria-label="Permalink to &quot;二、六大核心质量属性 ★&quot;">​</a></h3><p><strong>性能（Performance）：</strong></p><ul><li>系统的响应能力：响应时间（多久响应）、吞吐量（单位时间处理事件个数）</li><li>典型场景：&quot;并发 10 万用户时，请求响应时间 &lt; 3 秒&quot;</li><li>架构策略：<strong>资源调度</strong>、<strong>引入并发</strong>、增加计算资源</li></ul><p><strong>可用性（Availability）：</strong></p><ul><li>系统故障后恢复并继续提供服务的能力</li><li>指标：MTBF（故障间隔时间）、MTTR（修复时间）</li><li>典型场景：&quot;主站宕机后，10 秒内自动切换至备用站点&quot;</li><li>架构策略：<strong>心跳</strong>（故障检测）、<strong>主动冗余</strong>（主备切换）</li></ul><p><strong>安全性（Security）：</strong></p><ul><li>抵御恶意攻击的能力</li><li>典型场景：&quot;防止 99% 黑客攻击&quot;、&quot;对恶意操作进行报警和记录&quot;</li><li>架构策略：<strong>追踪审计</strong>、<strong>检测攻击</strong>、<strong>权限控制</strong></li></ul><p><strong>可修改性（Modifiability）：</strong></p><ul><li>定位修改点并实施修改的难易程度</li><li>典型场景：&quot;二次开发时间不超过 3 个月&quot;、&quot;功能调整不超过 1 人月&quot;</li><li>包含：可维护性、可扩展性、结构重构、可移植性</li><li>架构策略：<strong>抽象接口</strong>、<strong>信息隐藏</strong>、<strong>接口-实现分离</strong></li></ul><p><strong>可测试性（Testability）：</strong></p><ul><li>验证系统行为的难易程度</li><li>架构策略：记录/回放、内置监控器</li></ul><p><strong>易用性（Usability）：</strong></p><ul><li>用户使用体验</li><li>典型刺激：学习系统特性、有效使用系统、使错误影响最低、适配系统、对系统满意</li><li>注意区分：易用性聚焦 &quot;用户使用体验&quot;，可用性聚焦 &quot;系统在线时间&quot;</li></ul><h4 id="可靠性-reliability" tabindex="-1">可靠性（Reliability） <a class="header-anchor" href="#可靠性-reliability" aria-label="Permalink to &quot;可靠性（Reliability）&quot;">​</a></h4><blockquote><p>🎯 可靠性 = 在规定条件和时间内完成规定功能的能力，核心指标是 MTBF（平均失效间隔时间）。</p></blockquote><ul><li>在意外或错误使用情况下维持功能特性的能力</li><li>**MTTF（平均失效等待时间）**和 <strong>MTBF（平均失效间隔时间）</strong>：在失效率为常数且修复时间很短的情况下，<strong>MTTF 和 MTBF 几乎相等</strong></li><li>与可用性的区别：可靠性侧重&quot;不出错&quot;，可用性侧重&quot;出错后能恢复&quot;</li></ul><h4 id="鲁棒性-robustness" tabindex="-1">鲁棒性（Robustness） <a class="header-anchor" href="#鲁棒性-robustness" aria-label="Permalink to &quot;鲁棒性（Robustness）&quot;">​</a></h4><blockquote><p>🎯 鲁棒性 = 系统在非正常情况下（非法操作、硬件故障）下仍能正常运行的能力。属于运行期质量属性。</p></blockquote><ul><li>区别于可用性：鲁棒性关注系统<strong>承受压力或异常</strong>的能力，可用性关注<strong>恢复</strong>能力</li><li>题眼：&quot;用户进行了非法操作、相关软硬件发生故障&quot; → 鲁棒性</li></ul><h4 id="可变性-variability" tabindex="-1">可变性（Variability） <a class="header-anchor" href="#可变性-variability" aria-label="Permalink to &quot;可变性（Variability）&quot;">​</a></h4><blockquote><p>🎯 可变性 = 体系结构经扩充或变更成为新体系结构的能力。注意：归属为可修改性的子维度，但<strong>独立考察</strong>。</p></blockquote><ul><li>可修改性包含：可维护性、可扩展性、结构重构、可移植性</li><li>⚠️ 常见坑：可变性<strong>不属于</strong>可修改性的组成部分（它是并列概念）</li></ul><hr><h3 id="三、运行期-vs-开发期质量属性-★" tabindex="-1">三、运行期 vs 开发期质量属性 ★ <a class="header-anchor" href="#三、运行期-vs-开发期质量属性-★" aria-label="Permalink to &quot;三、运行期 vs 开发期质量属性 ★&quot;">​</a></h3><blockquote><p>🎯 开发期质量属性：关注开发和维护过程的效率；运行期质量属性：关注系统在线运行时的表现。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>包含属性</th><th>特点</th></tr></thead><tbody><tr><td><strong>运行期质量属性</strong></td><td>性能、安全性、可用性、可靠性、鲁棒性、互操作性</td><td>用户在使用时可直接感知</td></tr><tr><td><strong>开发期质量属性</strong></td><td>可修改性、可测试性、可重用性、可维护性、可移植性</td><td>开发和维护阶段体现</td></tr></tbody></table><p>⚠️ 常见坑：可伸缩性（Scalability）是运行期质量属性（与用户数和数据量相关）。</p><hr><h3 id="四、质量属性-架构策略速查表-★" tabindex="-1">四、质量属性-架构策略速查表 ★ <a class="header-anchor" href="#四、质量属性-架构策略速查表-★" aria-label="Permalink to &quot;四、质量属性-架构策略速查表 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>质量属性</th><th>典型场景关键词</th><th>首选架构策略</th></tr></thead><tbody><tr><td><strong>性能</strong></td><td>响应时间、并发用户数、时延</td><td><strong>资源调度</strong>、引入并发</td></tr><tr><td><strong>可用性</strong></td><td>宕机切换、自动恢复、双机热备</td><td><strong>心跳</strong>、<strong>主动冗余</strong></td></tr><tr><td><strong>安全性</strong></td><td>防攻击、加密、入侵检测、报警记录</td><td><strong>追踪审计</strong>、检测攻击</td></tr><tr><td><strong>可修改性</strong></td><td>二次开发、功能调整、替换中间件</td><td><strong>抽象接口</strong>、接口-实现分离</td></tr><tr><td><strong>可测试性</strong></td><td>测试、验证</td><td>记录/回放、内置监控器</td></tr><tr><td><strong>易用性</strong></td><td>操作一致性、用户满意度、学习成本</td><td>—</td></tr></tbody></table><hr><h3 id="五、敏感点、权衡点与风险决策-★" tabindex="-1">五、敏感点、权衡点与风险决策 ★ <a class="header-anchor" href="#五、敏感点、权衡点与风险决策-★" aria-label="Permalink to &quot;五、敏感点、权衡点与风险决策 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>定义</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>敏感点</strong></td><td>一个或多个构件/关系的特性，其微小变化会对<strong>某个</strong>质量属性产生显著影响</td><td>影响单个质量属性</td></tr><tr><td><strong>权衡点</strong></td><td>影响<strong>多个</strong>质量属性的特性，是多个质量属性的敏感点</td><td>涉及多属性取舍</td></tr><tr><td><strong>风险点</strong></td><td>可能导致架构失败的决策</td><td>潜在负面结果</td></tr><tr><td><strong>非风险点</strong></td><td>对质量属性无显著影响的决策</td><td>可接受</td></tr></tbody></table><blockquote><p><strong>典型考题</strong>：改变加密级别 → 权衡点（影响安全性 ↑ + 性能 ↓）</p></blockquote><p><strong>识别规律：</strong></p><ul><li>只涉及一个质量属性 → 敏感点</li><li>涉及两个及以上质量属性的取舍 → 权衡点</li></ul><hr><h3 id="六、atam-架构权衡分析方法" tabindex="-1">六、ATAM（架构权衡分析方法） <a class="header-anchor" href="#六、atam-架构权衡分析方法" aria-label="Permalink to &quot;六、ATAM（架构权衡分析方法）&quot;">​</a></h3><blockquote><p>ATAM 主要在系统开发之前，针对<strong>性能、可用性、安全性和可修改性</strong>等质量属性进行评价和折中。</p></blockquote><p><strong>四大活动阶段：</strong></p><ol><li>场景和需求收集</li><li>架构视图和场景实现</li><li><strong>属性模型构造和分析</strong>（核心步骤）</li><li>折中（权衡分析）</li></ol><p><strong>效用树（Utility Tree）：</strong></p><ul><li>ATAM 的重要工具，树形结构从根到叶：<strong>树根 → 质量属性 → 属性分类 → 质量属性场景</strong></li><li>用于系统化分析架构质量属性，从抽象目标到具体场景分解</li></ul><p><strong>核心概念：</strong> 整个评估过程强调以<strong>属性</strong>作为架构评估的核心概念。场景从**风险承担者（Stakeholder）**的角度描述。</p><hr><h3 id="七、saam-软件架构分析方法" tabindex="-1">七、SAAM（软件架构分析方法） <a class="header-anchor" href="#七、saam-软件架构分析方法" aria-label="Permalink to &quot;七、SAAM（软件架构分析方法）&quot;">​</a></h3><blockquote><p>SAAM 是最早形成文档并得到广泛应用的软件架构分析方法，最初主要用于评估<strong>可修改性</strong>。</p></blockquote><p><strong>五大评估步骤：</strong></p><ol><li><strong>场景开发</strong> — 体现系统所支持的各种活动</li><li><strong>架构描述</strong> — 定义系统组成</li><li><strong>单个场景评估</strong> — 逐一评估场景</li><li><strong>场景交互</strong> — 分析场景间的相互影响</li><li><strong>总体评估</strong> — 综合评价</li></ol><p><strong>三大输入：</strong></p><ol><li>问题描述</li><li>需求声明</li><li><strong>体系结构描述</strong>（必需的分析对象）</li></ol><blockquote><p>⚠️ SAAM 评估过程<strong>不包括</strong>属性模型构造（那是 ATAM 的步骤）。</p></blockquote><h3 id="八、cbam-成本效益分析法" tabindex="-1">八、CBAM（成本效益分析法） <a class="header-anchor" href="#八、cbam-成本效益分析法" aria-label="Permalink to &quot;八、CBAM（成本效益分析法）&quot;">​</a></h3><blockquote><p>🎯 CBAM 在 ATAM 基础上构建，核心依据是**投资回报率（ROI）**选择架构策略。是对 ATAM 的补充，在质量属性确定后，再从成本效益角度进行分析。</p></blockquote><p><strong>主要步骤：</strong></p><ol><li>整理场景</li><li>分配效用（为场景分配效用值）</li><li>形成&quot;策略-场景-响应级别&quot;的对应关系</li><li>使用内插法确定期望质量属性响应级别的效用</li><li>计算各架构策略的总收益</li><li>根据受成本影响的 ROI 选择架构策略</li></ol><blockquote><p>🎯 CBAM 关注的核心焦点：在考虑经济成本和效益的前提下，对架构策略进行优先级排序。</p></blockquote><h3 id="九、非功能性需求四分类" tabindex="-1">九、非功能性需求四分类 <a class="header-anchor" href="#九、非功能性需求四分类" aria-label="Permalink to &quot;九、非功能性需求四分类&quot;">​</a></h3><blockquote><p>🎯 架构设计中的非功能性需求分为四类，用于指导架构策略选择。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>典型示例</th></tr></thead><tbody><tr><td><strong>操作性需求</strong></td><td>与用户操作使用相关</td><td>界面个性化定制、支持主流标准协议</td></tr><tr><td><strong>性能需求</strong></td><td>响应时间、吞吐量、资源利用率</td><td>响应时间 ≤ 3s、支持 ≥ 2G 缓存</td></tr><tr><td><strong>安全性需求</strong></td><td>向合法用户服务、阻止非授权使用</td><td>密码加密传输、超时重登验证</td></tr><tr><td><strong>文化需求</strong></td><td>带有文化背景因素</td><td>支持多语言（汉语/英语/法语）</td></tr></tbody></table><p><strong>ATAM vs SAAM vs CBAM 对比总表：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>核心特点</th><th>关键输入</th><th>主要用途</th></tr></thead><tbody><tr><td>ATAM</td><td>质量属性建模与折中</td><td>质量需求、场景</td><td>多质量属性权衡</td></tr><tr><td>SAAM</td><td>场景驱动的架构评估</td><td>架构描述、问题声明</td><td>可修改性评估</td></tr><tr><td>CBAM</td><td>成本效益驱动的策略选择</td><td>ROI分析、效用分配</td><td>经济视角策略排序</td></tr></tbody></table>',71)])])}const q=o(s,[["render",a]]);export{b as __pageData,q as default};
